336	func (s *Store) validateDeploymentAuthenticationState(ctx context.Context, config *deploymentConfiguration) error {
337		_, generalConfigured := config.instanceSettings[storepb.InstanceSettingKey_GENERAL]
338		if !generalConfigured && len(config.identityProviders) == 0 {
339			general, err := s.getRawInstanceSetting(ctx, storepb.InstanceSettingKey_GENERAL.String())
340			if err != nil {
341				return errors.Wrap(err, "failed to inspect stored GENERAL setting")
342			}
343			if general == nil || !general.GetGeneralSetting().DisallowPasswordAuth {
344				return nil
345			}
346			providers, err := s.listStoredIdentityProviders(ctx, &FindIdentityProvider{})
347			if err != nil {
348				return errors.Wrap(err, "failed to inspect stored identity providers")
349			}
350			if len(providers) == 0 {
351				slog.Warn("stored configuration disables password authentication for regular users but has no identity provider; unrelated deployment files remain loadable because administrator password sign-in is available")
352			}
353			return nil
354		}
355		general, err := s.getRawInstanceSetting(ctx, storepb.InstanceSettingKey_GENERAL.String())
356		if err != nil {
357			return errors.Wrap(err, "failed to read stored GENERAL setting")
358		}
359		if configured := config.instanceSettings[storepb.InstanceSettingKey_GENERAL]; configured != nil {
360			general = cloneInstanceSetting(configured)
361		}
362		if general == nil || !general.GetGeneralSetting().DisallowPasswordAuth {
363			return nil
364		}
365		providers, err := s.listStoredIdentityProviders(ctx, &FindIdentityProvider{})
366		if err != nil {
367			return errors.Wrap(err, "failed to read stored identity providers")
368		}
369		effectiveUIDs := map[string]struct{}{}
370		for _, provider := range providers {
371			effectiveUIDs[provider.Uid] = struct{}{}
372		}
373		for uid := range config.identityProviders {
374			effectiveUIDs[uid] = struct{}{}
375		}
376		if len(effectiveUIDs) == 0 {
377			return errors.New("deployment configuration disables password authentication for regular users but has no effective identity provider")
378		}
379		return nil
380	}
